import Anthropic from "@anthropic-ai/sdk";
import * as z from "zod";

const client = new Anthropic();
const Booking = z.object({ name: z.string(), guests: z.number().int().min(1).max(20), date: z.iso.date() });

export async function viaTool(email: string) {
  const msg = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 1024,
    tools: [{
      name: "record_booking",
      description: "Record the booking found in the email. Use the guest's name exactly as written. Do not guess missing values.",
      strict: true, // вход инструмента генерируется под грамматикой схемы
      input_schema: {
        type: "object",
        properties: {
          name: { type: "string", description: "Guest full name as written in the email" },
          guests: { type: "integer", description: "Number of guests, 1 to 20" },
          date: { type: "string", format: "date", description: "Arrival date, YYYY-MM-DD" },
        },
        required: ["name", "guests", "date"],
        additionalProperties: false,
      },
    }],
    tool_choice: { type: "tool", name: "record_booking" }, // принудительно; некоторые модели ответят 400
    messages: [{ role: "user", content: email }],
  });

  const call = msg.content.find((b) => b.type === "tool_use");
  // Ничего не исполняется: call.input и есть структурированный ответ. SDK типизирует его как unknown.
  return Booking.safeParse(call?.input);
}

import * as z from "zod"; // Zod 4

const Booking = z.object({
  name: z.string(),
  guests: z.number().int().min(1).max(20),
  date: z.iso.date(), // YYYY-MM-DD
});

Booking.safeParse({ name: "Anna", guests: 2, date: "2026-10-03" });
// { success: true, data: { name: 'Anna', guests: 2, date: '2026-10-03' } }

const bad = Booking.safeParse({ name: "Anna", guests: "2", date: "2026-10-03" });
console.log(z.prettifyError(bad.error));
// ✖ Invalid input: expected number, received string
//   → at guests

const zero = Booking.safeParse({ name: "Anna", guests: 0, date: "3 Oct" });
console.log(z.prettifyError(zero.error));
// ✖ Too small: expected number to be >=1
//   → at guests
// ✖ Invalid ISO date
//   → at date

import Anthropic from "@anthropic-ai/sdk";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import * as z from "zod";

const client = new Anthropic();

// Мой контракт: строже, чем может обеспечить грамматика провайдера
const Booking = z.object({
  name: z.string().describe("Guest full name as written in the email"),
  guests: z.number().int().min(1).max(20),
  date: z.iso.date().describe("Arrival date, YYYY-MM-DD"),
});
type Booking = z.infer<typeof Booking>;

export async function extractBooking(email: string): Promise<Booking | null> {
  const messages: Anthropic.MessageParam[] = [
    { role: "user", content: "Extract the booking from this email:\n\n" + email },
  ];

  for (let attempt = 0; attempt < 3; attempt++) { // 1 попытка + 2 повтора
    const msg = await client.messages.create({
      model: "claude-sonnet-5",
      max_tokens: 1024,
      messages,
      output_config: { format: zodOutputFormat(Booking) },
    });

    // Отказ или обрыв: форма может быть сломана, и тот же запрос это не починит
    if (msg.stop_reason !== "end_turn") return null;

    const text = msg.content.find((b) => b.type === "text")?.text ?? "";
    let problem: string;
    try {
      const result = Booking.safeParse(JSON.parse(text));
      if (result.success) return result.data; // единственная дорога в базу
      problem = z.prettifyError(result.error);
    } catch (e) {
      problem = "Not valid JSON: " + (e as Error).message;
    }

    // Повтор: показываем модели её ответ и точную ошибку валидации
    messages.push(
      { role: "assistant", content: text },
      { role: "user", content: "Your JSON failed validation:\n" + problem + "\nReturn the corrected JSON." },
    );
  }
  return null; // вызывающий код: fallback + алерт; метрика доли невалидных растёт
}

